interface StoreIconProps extends IconProps {
	fillPercent?: number
	clipColor?: string
}

export const StoreIcon = ({
	fillPercent = 0.45,
	clipColor = '#376288',
	...props
}: StoreIconProps) => {
	const fillWidth = width * fillPercent
	const clipId = useMemo(
		() => `clip-${Math.random().toString(36).slice(2, 11)}`,
		[],
	)

	return (
		<Icon viewBox={viewBox} xmlns="http://www.w3.org/2000/svg" {...props}>
			<defs>
				<clipPath id={clipId}>
					<rect x="0" y="0" width={fillWidth} height={height} />
				</clipPath>
			</defs>

			{/* bgColor */}
			<IconPath color="currentColor" />

			{/* clipColor */}
			<g clipPath={`url(#${clipId})`}>
				<IconPath color={clipColor} />
			</g>
		</Icon>
	)
}
